mapper.select:
select consume.CID,
consume.CreateTime,
consume.Consume_Save_Balance,
consume.description,
consume.currentBalance,
user.UID,
user.UNAME,
card.Status,
sys_user_login.UserName
from consume,
sys_user_login,
user,card
where user.UID = sys_user_login.UID
and user.UID = consume.UID and card.CID = consume.CID

    and user.UID = #{uid}


    and CreateTime < #{endTime}


    and CreateTime > #{startTime}


    and consume.CID = #{cid}


    and UserName = #{username}

order by consume.CreateTime
